236	function parseRemotePath(path: string): {
237	  readonly pathname: string;
238	  readonly query: Readonly<Record<string, string>>;
239	} {
240	  if (typeof path !== "string" || !path.startsWith("/") || path.includes("#")) {
241	    throw new Error("Remote runtime path is invalid");
242	  }
243	  const [pathname, ...queryParts] = path.split("?");
244	  if (queryParts.length > 1 || !pathname) {
245	    throw new Error("Remote runtime path is invalid");
246	  }
247	  const query: Record<string, string> = {};
248	  if (queryParts.length === 1) {
249	    const rawQuery = queryParts[0];
250	    if (!rawQuery) {
251	      throw new Error("Remote runtime query is invalid");
252	    }
253	    for (const pair of rawQuery.split("&")) {
254	      const separatorIndex = pair.indexOf("=");
255	      if (separatorIndex <= 0) {
256	        throw new Error("Remote runtime query is invalid");
257	      }
258	      let key: string;
259	      let value: string;
260	      try {
261	        key = decodeURIComponent(pair.slice(0, separatorIndex));
262	        value = decodeURIComponent(pair.slice(separatorIndex + 1));
263	      } catch {
264	        throw new Error("Remote runtime query is invalid");
265	      }
266	      if (key in query) {
267	        throw new Error("Remote runtime query keys must be unique");
268	      }
269	      query[key] = value;
270	    }
271	  }
272	  return { pathname, query };
273	}
