350	def _history_cursor(
351	    *,
352	    created_at: str = "2026-08-23T00:00:00+00:00",
353	    message_id: str = "b" * 32,
354	) -> str:
355	    """Build one canonical bounded-history cursor for RPC validation tests."""
356	    created_at_bytes = created_at.encode("utf-8")
